import React from 'react';
import './EmployeeManagementPage.css';

// University-centric mock data
const employees = [
  { id: 101, name: 'Dr. Eleanor Vance', title: 'Professor', department: 'Computer Science', email: 'evance@university.edu' },
  { id: 102, name: 'Dr. Michael Chen', title: 'Associate Professor', department: 'Physics', email: 'mchen@university.edu' },
  { id: 103, name: 'Susan Martinez', title: 'Administrative Coordinator', department: 'Admissions Office', email: 'smartinez@university.edu' },
  { id: 104, name: 'David Lee', title: 'Lecturer', department: 'Mathematics', email: 'dlee@university.edu' },
  { id: 105, name: 'Dr. Sarah Kim', title: 'Dean of Arts & Sciences', department: 'Administration', email: 'skim@university.edu' },
];

const EmployeeManagementPage = () => {
  return (
    <div className="employee-management-container">
      <div className="page-header">
        <h1>University Staff & Faculty</h1> {/* Changed the title */}
        <button className="add-employee-btn">Add Staff/Faculty</button>
      </div>

      <div className="employee-table-container">
        <table className="employee-table">
          <thead>
            <tr>
              <th>ID</th>
              <th>Name</th>
              <th>Title</th> {/* Changed from Position */}
              <th>Department / Faculty</th> {/* More specific */}
              <th>Email</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {employees.map((employee) => (
              <tr key={employee.id}>
                <td>{employee.id}</td>
                <td>{employee.name}</td>
                <td>{employee.title}</td> {/* Changed from position */}
                <td>{employee.department}</td>
                <td>{employee.email}</td>
                <td className="actions">
                  <button className="action-btn edit">Edit</button>
                  <button className="action-btn delete">Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default EmployeeManagementPage;
